INSERT INTO dump_descriptions (base_key, description) VALUES ('minecraftbars', 'Replaces the standard health and armor display with Minecraft-style hearts and armor icons.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
